# Homebrew formula for thegn. Generated by packaging/release.py; do not edit.
#
# Homebrew does not attach com.apple.quarantine to formula downloads. The same
# unsigned tarball downloaded through a browser may be quarantined; see
# RELEASING.md. Apple silicon is the only currently verified macOS target.
class Thegn < Formula
  desc "Terminal-native git-worktree IDE that is its own terminal multiplexer"
  homepage "https://github.com/blakeashleyjr/thegn"
  version "0.1.0-alpha.142"
  license any_of: ["MIT", "Apache-2.0"]

  depends_on :macos
  depends_on arch: :arm64

  on_macos do
    on_arm do
      url "https://github.com/blakeashleyjr/thegn/releases/download/v0.1.0-alpha.142/thegn-v0.1.0-alpha.142-aarch64-apple-darwin.tar.gz"
      sha256 "529f8f221e06c5c77826b3053b74229aac46add3d37e72d9d359383be53e0dcc"
    end
  end

  depends_on "gh" => :optional
  depends_on "git-delta" => :optional
  depends_on "lazygit" => :optional

  def install
    bin.install "thegn"
    # Linux musl bridge pushed into Sprites/Vercel sandboxes; the host finds it
    # next to its own executable.
    bin.install "thegn-musl"
    bin.install_symlink "thegn" => "tg"
  end

  def caveats
    <<~EOS
      thegn is a TUI, so its launcher entry is a `thegn.app` bundle that opens a
      terminal running it. Generate one (it is not shipped — a locally generated
      bundle carries no com.apple.quarantine, so it needs no code signing):

        git clone https://github.com/blakeashleyjr/thegn
        cd thegn && just macos-app "#{bin}/thegn"

      macOS composes characters with the Option key by default, so thegn's
      Alt-based chords (Alt-w, Alt-o, Alt-s, Alt-.) will not reach it until your
      terminal is told to send Alt:

        Ghostty:    macos-option-as-alt = true
        Alacritty:  [window] option_as_alt = "Both"
        kitty:      macos_option_as_alt yes
    EOS
  end

  test do
    assert_match "thegn", shell_output("#{bin}/thegn --version")
  end
end
